/* C0/91AC  acceleration / auto-target integrator + subpixel->pixel converter.
   m=1 (A 8-bit) throughout; every ADC/LSR/EOR/INC is 8-bit mod 256.
   $XX = r[0x1D00+XX]; $0400/$01BC are absolute r[0x0400]/r[0x01BC]. */
void Ct_AccelIntegrate(uint8_t* r) {
  uint8_t* d = r + 0x1D00;

  /* (1) AUTO-TARGET HOLD  91AC-91F6.  Only when $00 != 0. */
  if (d[0x00] != 0) {                                  /* 91AC BEQ 91F8 */
    /* X axis (CMP: BCC <=> $02 < $0A) */
    if (d[0x02] == d[0x0A]) {                          /* 91B4 BEQ 91C4 */
      if ((d[0x87] & 0x0F) != 0) d[0x2E] = 0xF0;       /* 91C8 BNE 91BE: unsettled -> -16 */
      else d[0x01] |= 0x01;                            /* 91CA TSB $01,#$01 ($2E left = seed) */
    } else if (d[0x02] < d[0x0A]) {                    /* 91B6 BCC 91BE */
      d[0x2E] = 0xF0;                                  /* -16 */
    } else {
      d[0x2E] = 0x10;                                  /* 91B8 +16 */
    }
    /* Y axis -- NOTE: the $01==3 arrival check is INSIDE the y-arrived-settled branch */
    if (d[0x03] == d[0x0E]) {                          /* 91D2 BEQ 91E2 */
      if ((d[0x89] & 0x0F) != 0) {                     /* 91E6 BNE 91DC */
        d[0x30] = 0xF0;                                /* unsettled -> -16, then BRA 91F8 (NO arrival check) */
      } else {
        d[0x01] |= 0x02;                               /* 91E8 TSB $01,#$02, FALL INTO arrival check */
        if (d[0x01] == 0x03) {                         /* 91EC: ONLY reachable here */
          d[0x00] = 0x02;                              /* 91F2 advance state */
          d[0x01] = 0x00;                              /* 91F6 clear arrived flags */
        }
      }
    } else if (d[0x03] < d[0x0E]) {                    /* 91D4 BCC 91DC */
      d[0x30] = 0xF0;                                  /* -16, BRA 91F8 (skips check) */
    } else {
      d[0x30] = 0x10;                                  /* 91D6 +16, BRA 91F8 (skips check) */
    }
  }

  /* (2) FORCED-VECTOR IMPULSE  91F8-9236.  Only when $01BC != 0. */
  if (r[0x01BC] != 0) {                                /* 91FB BEQ 9238 */
    uint8_t c = r[0x0400];
    if (c & 0x01) {                                    /* 9200 BIT #$01 set -> negative */
      d[0x4E] = (uint8_t)(-(uint8_t)((c & 0x04) << 2));            /* 9216-921D */
      d[0x4F] = (uint8_t)(-(uint8_t)((r[0x0400] & 0x02) << 3));    /* 921F-9229 */
    } else {                                           /* positive */
      d[0x4E] = (uint8_t)((c & 0x04) << 2);            /* 9204-9208 (0 or 0x10) */
      d[0x4F] = (uint8_t)((r[0x0400] & 0x02) << 3);    /* 920A-9212 (0 or 0x10) */
    }
    if (d[0x0A] == 0) d[0x4E] = 0;                     /* 922C-9230 */
    if (d[0x0E] == 0) d[0x4F] = 0;                     /* 9232-9236 */
  }
  /* else $4E/$4F untouched (must be cleared elsewhere when not in forced mode). */

  /* (3) INTEGRATE INTO SIGNED 8.4 ACCUMULATORS  9238-92C8 (all 8-bit wrap). */
  d[0x3B] = (uint8_t)(d[0x2E] + d[0x3B] + d[0x24] + d[0x4E]);      /* 9238-9243 */
  d[0x3C] = (uint8_t)(d[0x30] + d[0x3C] + d[0x25] + d[0x4F]);      /* 9245-9250 */
  if (d[0x36] & 0x02) {                                /* 9254 BIT #$02 */
    d[0x3D] = (uint8_t)(d[0x37] + d[0x3D] + d[0x26]);              /* 9258-9260 */
    d[0x3E] = (uint8_t)(d[0x38] + d[0x3E] + d[0x27]);              /* 9262-926A */
  } else {
    d[0x3D] = (uint8_t)(d[0x2E] + d[0x37] + d[0x3D] + d[0x26] + d[0x4E]); /* 926E-927C */
    d[0x3E] = (uint8_t)(d[0x30] + d[0x38] + d[0x3E] + d[0x27] + d[0x4F]); /* 927E-928C */
  }
  if (d[0x36] & 0x04) {                                /* 9290 BIT #$04 */
    d[0x3F] = (uint8_t)(d[0x39] + d[0x3F] + d[0x28]);              /* 9294-929C */
    d[0x40] = (uint8_t)(d[0x3A] + d[0x40] + d[0x29]);              /* 929E-92A6 */
  } else {
    d[0x3F] = (uint8_t)(d[0x2E] + d[0x39] + d[0x3F] + d[0x28] + d[0x4E]); /* 92AA-92B8 */
    d[0x40] = (uint8_t)(d[0x30] + d[0x3A] + d[0x40] + d[0x29] + d[0x4F]); /* 92BA-92C8 */
  }

  /* (4) SUBPIXEL -> SIGNED-SPLIT INTEGER PIXELS  92CA-93CA.
     pixels = |acc| >> 4 (truncate toward zero); split by sign; acc := sign-extended low nibble. */
  static const uint8_t accAddr[6] = {0x3B,0x3C,0x3D,0x3E,0x3F,0x40};
  static const uint8_t negSlot[6] = {0x41,0x43,0x45,0x47,0x49,0x4B};
  static const uint8_t posSlot[6] = {0x42,0x44,0x46,0x48,0x4A,0x4C};
  for (int k = 0; k < 6; ++k) {
    uint8_t a = d[accAddr[k]];
    if ((int8_t)a < 0) {                               /* BMI taken */
      uint8_t mag = (uint8_t)(((a ^ 0xFF) + 1));       /* EOR FF / INC A */
      d[negSlot[k]] = (uint8_t)(mag >> 4);             /* 4x LSR */
      d[posSlot[k]] = 0;
    } else {
      d[posSlot[k]] = (uint8_t)(a >> 4);
      d[negSlot[k]] = 0;
    }
    if ((a & 0x0F) == 0)     d[accAddr[k]] = 0;
    else if ((int8_t)a >= 0) d[accAddr[k]] = (uint8_t)(a & 0x0F);
    else                     d[accAddr[k]] = (uint8_t)(a | 0xF0);
  }

  /* (5) ACCEL-BIAS TIMEOUT  93CC-93E0. */
  if (d[0x4D] != 0) {                                  /* 93CC BEQ 93E0 */
    if (--d[0x4D] == 0)                                /* 93D0 DEC, 93D2 BNE 93E0 */
      d[0x24] = d[0x25] = d[0x26] = d[0x27] = d[0x28] = d[0x29] = 0; /* 93D4-93DE */
  }
  /* 93E0 RTS -> caller C0/8855 enters the 93E1 step/collision tree (consumes $41..$4C). */
}
